//! Immutable task output artifacts. Public descriptors never contain host paths.
use crate::{Shared,Res,locked,core,assistant::Output};use serde_json::{Value,json};use sha2::{Sha256,Digest};use std::path::{Path,PathBuf};
fn manifest(root:&Path,id:&str)->PathBuf{root.join(format!("{id}.outputs"))}
fn read_manifest(root:&Path,id:&str)->Value{std::fs::read(manifest(root,id)).ok().and_then(|b|serde_json::from_slice(&b).ok()).unwrap_or_else(||json!({}))}
pub(crate) fn descriptors(root:&Path,id:&str)->Vec<Value>{read_manifest(root,id).as_object().map(|entries|entries.values().cloned().collect()).unwrap_or_default()}
fn extension(format:&str)->&str{if format=="jpeg"{"jpg"}else{format}}
pub(crate) fn write(s:&Shared,root:&Path,id:&str,project:&core::Project,aid:&str,output:Option<&Output>)->Res<Value>{write_config(s,root,id,project,aid,output,None)}
pub(crate) fn write_config(s:&Shared,root:&Path,id:&str,project:&core::Project,aid:&str,output:Option<&Output>,options:Option<&Value>)->Res<Value>{
 uuid::Uuid::parse_str(id).map_err(|_|"INVALID_TASK_ID")?;uuid::Uuid::parse_str(aid).map_err(|_|"INVALID_ASSET_ID")?;
 let store=locked(s)?;if Some(store.root.as_path())!=root.parent(){return Err("DATA_ROOT_CHANGED".into())}let mut asset=project.assets.iter().find(|a|a.id==aid).ok_or("ASSET_NOT_FOUND")?.clone();if let Some(version)=asset.versions.iter().find(|v|v.generation.as_ref().is_some_and(|g|g["operationTask"]==id)).or_else(||asset.versions.iter().find(|v|v.generation.as_ref().is_some_and(|g|g["hybridJobId"]==id))){asset.generated_base=Some(version.id.clone());asset.edit=core::Edit::default();}let snapshot=core::Project{id:project.id.clone(),name:project.name.clone(),created_at:project.created_at,updated_at:project.updated_at,assets:vec![asset.clone()]};let image=core::render(store.source(&snapshot,aid)?,&asset.edit,None)?;drop(store);let empty=json!({});let mut preset=crate::frontend_export::preset(options.unwrap_or(&empty),image.width(),image.height())?;if let Some(output)=output{preset.format=output.format.clone();preset.width=output.width;preset.height=output.height;preset.fit=output.fit.clone();preset.max_bytes=output.max_bytes;preset.background=output.background;}let output=Output{format:preset.format.clone(),width:preset.width,height:preset.height,fit:preset.fit.clone(),max_bytes:preset.max_bytes,background:preset.background};
 let mut image=core::fit(&image,preset.width,preset.height,preset.fit=="pad",preset.background);if preset.format=="jpeg"{image=core::flatten(&image,preset.background)}
 let(bytes,quality)=core::encode_target(&image,&preset)?;
 let ext=extension(&output.format);let stem=Path::new(&asset.name).file_stem().and_then(|s|s.to_str()).unwrap_or("image");let name=format!("{stem}.{ext}");let ok=output.max_bytes==0||bytes.len() as u64<=output.max_bytes;let digest=format!("{:x}",Sha256::digest(&bytes));let value=json!({"assetId":aid,"name":name,"format":output.format,"bytes":bytes.len(),"sha256":digest,"width":image.width(),"height":image.height(),"quality":quality,"status":if ok{"ok"}else{"EXPORT_TARGET_UNREACHABLE"}});
 if ok{let directory=root.parent().ok_or("TASK_STORAGE")?.join("exports").join(id);std::fs::create_dir_all(&directory).map_err(|_|"OUTPUT_UNAVAILABLE")?;crate::frontend_settings::atomic_bytes(&directory,&format!("{aid}.{ext}"),&bytes)?;}
 let mut entries=read_manifest(root,id);entries[aid]=value.clone();crate::frontend_settings::atomic_bytes(root,&format!("{id}.outputs"),&serde_json::to_vec(&entries).map_err(|_|"OUTPUT_UNAVAILABLE")?)?;Ok(value)
}
pub(crate) fn result(s:&Shared,id:&str,aid:&str)->Res<Vec<u8>>{uuid::Uuid::parse_str(id).map_err(|_|"INVALID_TASK_ID")?;uuid::Uuid::parse_str(aid).map_err(|_|"INVALID_ASSET_ID")?;let task=crate::frontend_ops::existing(s,id)?.ok_or("TASK_NOT_FOUND")?;if task["assetIds"].as_array().is_none_or(|ids|!ids.iter().any(|value|value==aid)){return Err("RESULT_NOT_FOUND".into())}let data_root=locked(s)?.root.clone();let root=data_root.join("operation-jobs");let entries=read_manifest(&root,id);let entry=&entries[aid];if entry["status"]!="ok"{return Err("RESULT_NOT_AVAILABLE".into())}let format=entry["format"].as_str().filter(|s|["webp","png","jpeg"].contains(s)).ok_or("RESULT_NOT_FOUND")?;let bytes=std::fs::read(data_root.join("exports").join(id).join(format!("{aid}.{}",extension(format)))).map_err(|_|"RESULT_NOT_FOUND")?;if entry["bytes"].as_u64()!=Some(bytes.len() as u64)||entry["sha256"]!=format!("{:x}",Sha256::digest(&bytes)){return Err("RESULT_CHANGED".into())}Ok(bytes)}
